fn main() {
    // Create a Box containing a vector of integers
    let mut boxed_vec: Box<Vec<i32>> = Box::new(Vec::new());

    // Push elements into the vector
    boxed_vec.push(1);
    boxed_vec.push(2);
    boxed_vec.push(3);

    // Assert that the vector length is correct after pushing elements
    assert_eq!(boxed_vec.len(), 3, "Vector length should be 3 after pushing 3 elements");

    // Move the Box into a function to test memory management
    let result = process_box(boxed_vec);

    // Assert that the function returned the expected length (proving no leak)
    assert_eq!(result, 3, "Memory should not leak; length should remain 3");

    println!("success");
}

fn process_box(mut boxed_vec: Box<Vec<i32>>) -> usize {
    // Access the length inside the function
    let len = boxed_vec.len();
    // Return the length to prove the Box was moved correctly and memory is managed
    len
}
